import unittest
from pathlib import Path

from omw.remote import build_refusal, fetch_note, lacking, linked, remote_line, remote_script, sonames
from omw.system import WINDOWS, Refusal


class LibrariesTest(unittest.TestCase):
    def test_the_libraries_the_other_machine_lacks_are_the_linked_ones_it_names_no_soname_of(self):
        offered = sonames(
            "1234 libs found in cache `/etc/ld.so.cache'\n"
            "\tlibz.so.1 (libc6,x86-64) => /usr/lib/libz.so.1\n"
            "\tlibvulkan.so.1 (libc6,x86-64) => /usr/lib/libvulkan.so.1\n"
            "Cache generated by: ldconfig (GNU libc) release version 2.43\n")
        self.assertEqual(offered, {"libz.so.1", "libvulkan.so.1"})

        # The vDSO, the loader and a library that did not resolve name no file to copy; a library
        # listed twice, by the binary and by a plugin, is one.
        libraries = linked(
            "/build/openmw-rtxtool:\n"
            "\tlinux-vdso.so.1 (0x00007ffd)\n"
            "\tlibz.so.1 => /lib/x86_64-linux-gnu/libz.so.1 (0x00007f00)\n"
            "\tlibosg.so.162 => /lib/x86_64-linux-gnu/libosg.so.162 (0x00007f01)\n"
            "\tlibgone.so.3 => not found\n"
            "\t/lib64/ld-linux-x86-64.so.2 (0x00007f02)\n"
            "/osgPlugins-3.6.5/osgdb_png.so:\n"
            "\tlibosg.so.162 => /lib/x86_64-linux-gnu/libosg.so.162 (0x00007f01)\n"
            "\tlibpng16.so.16 => /lib/x86_64-linux-gnu/libpng16.so.16 (0x00007f03)\n")
        self.assertEqual(libraries, {
            "libz.so.1": "/lib/x86_64-linux-gnu/libz.so.1",
            "libosg.so.162": "/lib/x86_64-linux-gnu/libosg.so.162",
            "libpng16.so.16": "/lib/x86_64-linux-gnu/libpng16.so.16",
        })
        self.assertEqual(list(lacking(libraries, offered)), ["libosg.so.162", "libpng16.so.16"])


@unittest.skipIf(WINDOWS, "remote is Linux's")
class BuildFolderTest(unittest.TestCase):
    def test_a_host_that_does_not_answer_is_told_from_a_folder_it_cannot_write(self):
        parent = Path("/home/deck/Projects/openmw")
        self.assertIsNone(build_refusal("deck@deck", parent, 0))
        self.assertEqual(build_refusal("deck@deck", parent, 255),
                         "remote: ssh reached no shell on deck@deck, as it says above")
        self.assertEqual(build_refusal("deck@deck", parent, 1),
                         "deck@deck cannot write /home/deck/Projects/openmw, where the build goes: make it once there "
                         "with `sudo mkdir -p /home/deck/Projects/openmw && sudo chown $USER: /home/deck/Projects/openmw`")

    def test_a_file_the_run_did_not_write_is_told_from_a_copy_that_failed(self):
        self.assertEqual(fetch_note(0), "")
        self.assertEqual(fetch_note(23), " was not written there")
        self.assertEqual(fetch_note(255), " could not be brought back: rsync exited 255")
        self.assertEqual(fetch_note(12), " could not be brought back: rsync exited 12")


# The two machines' paths are one Linux path, and `remote` refuses on Windows: there `Path` spells
# them with backslashes, as no machine the line goes to reads them.
@unittest.skipIf(WINDOWS, "remote is Linux's")
class RemoteLineTest(unittest.TestCase):
    def test_a_path_the_run_writes_or_reads_is_made_absolute_in_either_form(self):
        here = Path("/desk/tree")
        line = remote_line(["--views=ship", "--json", "out.json", "--frame-times=/abs/times", "--against=base",
                            "--window=true"], "bench", here)
        self.assertEqual(line.args, ["--views=ship", "--json=/desk/tree/out.json", "--frame-times=/abs/times",
                                     "--against=/desk/tree/base", "--window=true"])
        self.assertEqual(line.outputs, [Path("/desk/tree/out.json"), Path("/abs/times")])
        self.assertEqual(line.inputs, [Path("/desk/tree/base")])

    def test_a_bench_with_nothing_said_of_a_window_runs_without_one_and_nothing_else_is_told(self):
        self.assertEqual(remote_line(["--views=ship"], "bench", Path("/")).args, ["--views=ship", "--window=false"])
        self.assertEqual(remote_line(["--window", "--views=ship"], "bench", Path("/")).args,
                         ["--window", "--views=ship"])
        self.assertEqual(remote_line(["--views=ship"], "shot", Path("/")).args, ["--views=ship"])

    def test_a_path_is_made_absolute_without_reading_the_links_of_this_machine(self):
        self.assertEqual(remote_line(["--keys=../keys.txt"], "film", Path("/desk/tree/sub")).inputs,
                         [Path("/desk/tree/keys.txt")])

    def test_a_switch_that_names_no_path_or_a_path_only_this_machine_has_is_refused(self):
        for line in (["--json"], ["--perf-control=/tmp/fifo"]):
            with self.subTest(line=line), self.assertRaises(Refusal):
                remote_line(line, "bench", Path("/"))


@unittest.skipIf(WINDOWS, "remote is Linux's")
class RemoteScriptTest(unittest.TestCase):
    def test_the_run_is_the_harness_under_its_libraries_and_a_measured_one_holds_the_clock(self):
        folder = Path("/home/me/tree/build-release")
        script = remote_script(folder, "bench", ["--views=a b"], measured=True)
        lines = script.splitlines()
        self.assertEqual(lines[1], "cd /home/me/tree/build-release")
        self.assertIn("LD_LIBRARY_PATH=/home/me/tree/build-release/remote-lib", lines[2])
        self.assertIn("WAYLAND_DISPLAY=wayland-0 SDL_VIDEO_DRIVER=wayland", lines[3])
        self.assertIn("else export SDL_VIDEO_DRIVER=offscreen", lines[3])
        self.assertEqual(lines[-1], "./openmw-rtxtool bench '--views=a b'")
        self.assertIn("GpuPerformanceLevel s manual", script)
        # Put back on the way out, which an exec would never reach.
        self.assertIn("trap 'gpu set-property GpuPerformanceLevel s \"$level\"; [ \"$level\" = manual ]", script)
        self.assertNotIn("exec ", script)

        unmeasured = remote_script(folder, "shot", [], measured=False)
        self.assertNotIn("steamos", unmeasured.lower())
        self.assertEqual(unmeasured.splitlines()[-1], "./openmw-rtxtool shot")


if __name__ == "__main__":
    unittest.main()
